window.RP_SESSION={"id":"S-6aac038245ae","messages":[{"id":"RP-0111320","time":"2026-04-13T08:08:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"\"감기 걸렸나~ 봐요~\"\n\n 길드 이곳저곳을 돌아다니는 한 광대가 있다. \n그는 마구간 앞에서 멈춰 서더니...\n\n\"스텔라? 부길드장?\"\n\n 있지도 않은 스텔라를 부르며 마구간으로 들어간다.","characters":["P-c2ae9261373e"]},{"id":"RP-0111321","time":"2026-04-13T08:15:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"'빼꼼-'\n\n\"안녕하세요?\"\n\n 마구간에 있는 말들에게 인사를 하곤, 마구간 안을 쭉 둘러봅니다.\n\n\"가면 다시 쓰게?\"\n\n 그 후, 폴짝폴짝 뛰며 말 한 마리 앞에 다가서서 녀석에게 손을 내밉니다.\n\n\"하일로 조바?\"","characters":["P-c2ae9261373e"]},{"id":"RP-0111322","time":"2026-04-13T08:17:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-c2ae9261373e"]},{"id":"RP-0111323","time":"2026-04-13T08:17:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 8 = 8\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-0111324","time":"2026-04-13T08:24:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"'이히힝~'\n\n 말이 그의 손에 코를 가져다 대네요\n\n\"촉촉.. 부드러움...\"\n\n\"...\"\n\n\"아! 주황색 곱슬머리! 스텔라!\"\n\n 말을 쓰다듬다 말고 다시 폴짝폴짝 뛰며 스텔라를 찾으러 가는 라쿠나..","characters":["P-c2ae9261373e"]},{"id":"RP-0111325","time":"2026-04-13T09:18:00+09:00","room":"RP","name":"우슬라","profile":"위크 골든리프","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n라쿠나의 기행을 멀리서 지켜보던 우슬라\n\n\"...특이한 친구구먼.\"","characters":["P-d077092ffb19"]},{"id":"RP-0111326","time":"2026-04-13T11:30:00+09:00","room":"RP","name":"라쿠나","profile":"테론 이스트가드","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-c2ae9261373e"]},{"id":"RP-0111327","time":"2026-04-13T11:30:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... 계속.","characters":[]}]};
